startShot.example:
const { Vector3 } = kcds.math;

kcds.ui.Camera.startShot(player, {
  position: new Vector3(100, 200, 25),
  lookAt: new Vector3(110, 210, 12),
  fov: 50,
  seconds: 3,
});

playPath.example:
// client
const { Camera } = kcds.ui;
const { Vector3 } = kcds.math;

const square = new Vector3(512, 830, 31);
Camera.playPath(
  [
    { position: new Vector3(480, 800, 45), lookAt: square, time: 0 },
    { position: new Vector3(540, 800, 40), lookAt: square, time: 6 },
    { position: new Vector3(545, 860, 36), lookAt: square, time: 12, fov: 45 },
  ],
  { smooth: true },
);
kcds.core.Events.on('cameraPathFinished', () => Camera.endShot());

playPath.exampleCs:
// client
var square = new Vector3(512, 830, 31);
Camera.PlayPath(
    new object[]
    {
        new { position = new Vector3(480, 800, 45), lookAt = square, time = 0 },
        new { position = new Vector3(540, 800, 40), lookAt = square, time = 6 },
        new { position = new Vector3(545, 860, 36), lookAt = square, time = 12, fov = 45 },
    },
    new { smooth = true });
// In the player's game EndShot takes no player (C# names the server's parameter).
Events.On("cameraPathFinished", () => Camera.EndShot(null));

shake.example:
