getPose.example:
// client
const pose = kcds.ui.Camera.getPose();
if (pose) {
  console.info(`looking ${pose.forward}, fov ${pose.fov.toFixed(1)}`);
}

getPose.exampleCs:
// client
var pose = Camera.GetPose();
if (pose)
{
    Log.Info($"looking {pose["forward"]}, fov {pose["fov"].AsNumber().ToString("F1")}");
}

rayFromScreen.example:
// client: what is under the crosshair, up to 30 metres away
const ray = kcds.ui.Camera.rayFromScreen({ range: 30 });
const hit = ray && kcds.world.World.raycast(ray.origin, ray.target, { mode: 'anything' });
if (hit) {
  console.info(hit.kind, hit.entityClass ?? hit.model ?? hit.surface);
}

rayFromScreen.exampleCs:
// client: what is under the crosshair, up to 30 metres away
var ray = Camera.RayFromScreen(new { range = 30 });
if (!ray.IsNull)
{
    var hit = await World.Raycast(ray["origin"], ray["target"], new { mode = "anything" });
    if (!hit.IsNull)
    {
        var what = !hit["entityClass"].IsNull ? hit["entityClass"] : !hit["model"].IsNull ? hit["model"] : hit["surface"];
        Log.Info($"{hit["kind"]} {what}");
    }
}
